starter.versions.tf:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "topic_name" {
  description = "Input variable topic_name."
  type        = string
  default     = "events"
}

variable "queue_name" {
  description = "Input variable queue_name."
  type        = string
  default     = "events-queue"
}

variable "project_name" {
  description = "Input variable project_name."
  type        = string
  default     = "terraform-practice"
}

variable "environment" {
  description = "Input variable environment."
  type        = string
  default     = "dev"
}

variable "aws_region" {
  description = "Input variable aws_region."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_sns_topic" "this" {
  name = "app-topic"
}

resource "aws_sqs_queue" "this" {
  name                    = "app-queue"
  sqs_managed_sse_enabled = true
}

resource "aws_sns_topic_subscription" "this" {
  # TODO - Complete the aws_sns_topic_subscription resource.
  # Add the arguments and nested blocks required for aws_sns_topic_subscription.
}

starter.outputs.tf:
output "topic_arn" {
  value = aws_sns_topic.this.arn
}

output "queue_url" {
  value = aws_sqs_queue.this.url
}
